import { useDataProvider, useEvent, } from 'react-admin';
import { useMutation, } from '@tanstack/react-query';
/**
 * Internal hook used to lazy load a node children using the dataProvider.getChildNodes() method.
 *
 * @param {string} resource The resource name, e.g. 'posts'
 * @param {Params} params The getChildNodes parameters
 * @param {Object} options Options object to pass to the queryClient.
 * May include side effects to be executed upon success or failure, e.g. { onSuccess: () => { refresh(); } }
 *
 * @typedef Params
 * @prop params.parentId The parent node identifier
 * @prop params.meta Optional meta parameters

 * The data structure is a flat array of TreeRecords (i.e. Records with a children field containing an array of Identifiers).
 *
 * @example // sample return value
 * [
 *   { id: 1, title: 'foo1', children: [3, 4] },
 *   { id: 2, title: 'foo2', children: [] },
 *   { id: 3, title: 'foo3', children: [5] },
 *   { id: 4, title: 'foo4', children: [] },
 *   { id: 5, title: 'foo5', children: [] },
 * ]
 */
export const useGetChildNodesCallback = (resource, params, options) => {
    const dataProvider = useDataProvider();
    const mutation = useMutation({
        mutationKey: [resource, 'getChildNodes', params],
        mutationFn: variables => dataProvider
            .getChildNodes(resource, {
            ...params,
            ...variables,
        })
            .then(({ data }) => data),
        ...options,
    });
    const callback = useEvent((parentId) => {
        return mutation.mutateAsync({ ...params, parentId });
    });
    return callback;
};
