export const removeNode = (data, node) => {
    let newNodes = data.filter(r => r.id !== node.id);
    const parentNode = newNodes.find(r => r.children?.includes(node.id));
    if (parentNode) {
        parentNode.children = parentNode.children?.filter(id => id !== node.id);
    }
    if (!node.children || node.children.length === 0) {
        return newNodes;
    }
    const childrenIdsToRemove = getNodeChildrenRecursive(newNodes, node);
    newNodes = newNodes.filter(r => !childrenIdsToRemove.includes(r));
    return newNodes;
};
const getNodeChildrenRecursive = (data, node) => {
    if (!node) {
        return [];
    }
    if (!node.children || node.children.length === 0) {
        return [];
    }
    return [
        ...node.children,
        ...node.children.flatMap(childId => {
            const child = data.find(r => r.id === childId);
            if (!child) {
                return [];
            }
            return getNodeChildrenRecursive(data, child);
        }),
    ];
};
