import { deleteBranchByDeletingAllChildren } from './deleteBranchByDeletingAllChildren';
import { deleteBranchByDeletingNode } from './deleteBranchByDeletingNode';
/**
 * Provided the records contain a parent_id and a position field,
 * augment a dataProvider by adding the Tree methods (getTree, getRootNodes, etc).
 *
 * These methods will call regular dataProvider methods (getList, getOne, update).
 *
 * @warning Do not use in production.
 *
 * The added Tree methods call the API way too much, sometimes asking for the
 * entire tree. In practice, you should implement an optimized API route for
 * each of the Tree methods.
 *
 * @example // Compatible APIs should return records like
 * {
 *     id: 1234,
 *     name: 'hello',
 *     parent_id: 35,
 *     position: 4, // zero-based
 * }
 *
 * @param {DataProvider} dataProvider The dataProvider to augment
 * @param {string} parentIdField The name of the field containing the parent id. Defaults to 'parent_id'
 * @param {string} positionField The name of the field containing the position of a node inside its parent. Defaults to 'position'
 * @param {boolean} apiSupportBranchDeletion Indicates whether the API will handle children deletion when deleting a node as well as the siblings update. If false, the dataProvider will handle it by making multiple requests in the right order. Defaults to `false`.
 */
export const addTreeMethodsBasedOnParentAndPosition = (dataProvider, parentIdField = 'parent_id', positionField = 'position', apiSupportBranchDeletion = false) => {
    const deleteBranch = apiSupportBranchDeletion
        ? deleteBranchByDeletingNode
        : deleteBranchByDeletingAllChildren;
    const treeDataProvider = {
        ...dataProvider,
        getTree: async (resource, params) => {
            // get all records
            const { data } = await dataProvider.getList(resource, {
                filter: params?.filter,
                sort: { field: positionField, order: 'ASC' },
                pagination: { page: 1, perPage: 1000 },
                meta: params?.meta,
            });
            // fill children for each record
            // FIXME o(n2)
            const treeRecords = data.map(record => ({
                ...record,
                children: data
                    // eslint-disable-next-line eqeqeq
                    .filter(r => r[parentIdField] == record.id)
                    .sort((a, b) => a[positionField] - b[positionField])
                    .map(child => child.id),
            }));
            return {
                data: treeRecords,
            };
        },
        getRootNodes: async (resource, params) => {
            // get root records
            const { data } = await dataProvider.getList(resource, {
                filter: { ...params?.filter, [parentIdField]: null },
                sort: { field: positionField, order: 'ASC' },
                pagination: { page: 1, perPage: 1000 },
                meta: params?.meta,
            });
            // fill children for each record
            const treeRecords = await Promise.all(data.map(record => dataProvider
                .getList(resource, {
                filter: { [parentIdField]: record.id },
                sort: {
                    field: positionField,
                    order: 'ASC',
                },
                pagination: { page: 1, perPage: 1000 },
                meta: params?.meta,
            })
                .then(({ data }) => ({
                ...record,
                children: data.map(({ id }) => id),
            }))));
            return {
                data: treeRecords,
            };
        },
        getParentNode: async (resource, { childId, meta }) => {
            const { data: tree } = await treeDataProvider.getTree(resource, { meta });
            const child = tree.find(node => node.id === childId);
            if (!child) {
                return { data: undefined };
            }
            const parent = tree.find(node => node.id === child[parentIdField]);
            return {
                data: parent,
            };
        },
        getChildNodes: async (resource, { parentId, meta }) => {
            // get child records
            const { data } = await dataProvider.getList(resource, {
                filter: { [parentIdField]: parentId },
                sort: { field: positionField, order: 'ASC' },
                pagination: { page: 1, perPage: 1000 },
                meta,
            });
            // fill children for each record
            const treeRecords = await Promise.all(data.map(record => dataProvider
                .getList(resource, {
                filter: { [parentIdField]: record.id },
                sort: {
                    field: positionField,
                    order: 'ASC',
                },
                pagination: { page: 1, perPage: 1000 },
                meta,
            })
                .then(({ data }) => ({
                ...record,
                children: data.map(({ id }) => id),
            }))));
            return {
                data: treeRecords,
            };
        },
        moveAsNthChildOf: async (resource, { source, destination, position, meta }) => {
            // 1. Increment the position of all destination child nodes after the position
            const destinationSiblings = (await dataProvider.getList(resource, {
                filter: {
                    [parentIdField]: destination.id,
                    [`${positionField}_gte`]: position,
                },
                sort: {
                    field: positionField,
                    order: 'ASC',
                },
                pagination: { page: 1, perPage: 1000 },
                meta,
            })).data;
            if (destinationSiblings.length > 0) {
                await Promise.all(destinationSiblings.map(item => dataProvider.update(resource, {
                    id: item.id,
                    data: { [positionField]: item[positionField] + 1 },
                    previousData: item,
                    meta,
                })));
            }
            // 2. Decrement the position of all nodes after the source node
            const sourceSiblings = (await dataProvider.getList(resource, {
                filter: {
                    [parentIdField]: source[parentIdField],
                    [`${positionField}_gt`]: source[positionField],
                },
                sort: {
                    field: positionField,
                    order: 'ASC',
                },
                pagination: { page: 1, perPage: 1000 },
                meta,
            })).data;
            if (sourceSiblings.length > 0) {
                await Promise.all(sourceSiblings.map(item => dataProvider.update(resource, {
                    id: item.id,
                    data: { [positionField]: item[positionField] - 1 },
                    previousData: item,
                    meta,
                })));
            }
            // 3. Change the parent and position of the source node
            const { data: newRecord } = await dataProvider.update(resource, {
                id: source.id,
                data: {
                    [parentIdField]: destination.id,
                    [positionField]: position,
                },
                previousData: source,
                meta,
            });
            return { data: newRecord };
        },
        moveAsNthSiblingOf: async (resource, { source, destination, position, meta }) => {
            // 1. Increment the position of all nodes after the destination
            let destinationSiblingsToUpdateFilter;
            if (position === 0 || position === -1) {
                destinationSiblingsToUpdateFilter = {
                    [parentIdField]: destination[parentIdField],
                };
            }
            if (source[positionField] > destination[positionField] &&
                source[parentIdField] === destination[parentIdField]) {
                if (position === -1) {
                    destinationSiblingsToUpdateFilter = {
                        [parentIdField]: destination[parentIdField],
                        [`${positionField}_gte`]: destination[positionField],
                    };
                }
                else {
                    destinationSiblingsToUpdateFilter = {
                        [parentIdField]: destination[parentIdField],
                        [`${positionField}_gt`]: destination[positionField],
                    };
                }
            }
            if (source[parentIdField] !== destination[parentIdField] &&
                position > 0) {
                destinationSiblingsToUpdateFilter = {
                    [parentIdField]: destination[parentIdField],
                    [`${positionField}_gt`]: destination[positionField],
                };
            }
            if (destinationSiblingsToUpdateFilter) {
                const { data: destinationSiblings } = await dataProvider.getList(resource, {
                    filter: destinationSiblingsToUpdateFilter,
                    sort: {
                        field: positionField,
                        order: 'ASC',
                    },
                    pagination: { page: 1, perPage: 1000 },
                    meta,
                });
                if (destinationSiblings.length > 0) {
                    await Promise.all(destinationSiblings.map(item => item.id === source.id
                        ? Promise.resolve(undefined)
                        : dataProvider.update(resource, {
                            id: item.id,
                            data: {
                                [positionField]: item[positionField] + 1,
                            },
                            previousData: item,
                            meta,
                        })));
                }
            }
            // 2. Decrement the position of all nodes after the source node
            let sourceSiblingsToUpdateFilters;
            if (source[parentIdField] === destination[parentIdField]) {
                if (source[positionField] > destination[positionField]) {
                    sourceSiblingsToUpdateFilters = {
                        [parentIdField]: source[parentIdField],
                        [`${positionField}_gt`]: source[positionField],
                    };
                }
                else {
                    sourceSiblingsToUpdateFilters = {
                        [parentIdField]: source[parentIdField],
                        [`${positionField}_gt`]: source[positionField],
                        [`${positionField}_lte`]: destination[positionField],
                    };
                }
            }
            else {
                sourceSiblingsToUpdateFilters = {
                    [parentIdField]: source[parentIdField],
                    [`${positionField}_gt`]: source[positionField],
                };
            }
            const sourceSiblings = (await dataProvider.getList(resource, {
                filter: sourceSiblingsToUpdateFilters,
                sort: {
                    field: positionField,
                    order: 'ASC',
                },
                pagination: { page: 1, perPage: 1000 },
                meta,
            })).data;
            if (sourceSiblings.length > 0) {
                await Promise.all(sourceSiblings.map(item => item.id === source.id
                    ? Promise.resolve(undefined)
                    : dataProvider.update(resource, {
                        id: item.id,
                        data: {
                            [positionField]: item[positionField] - 1,
                        },
                        previousData: item,
                        meta,
                    })));
            }
            // 3. Change the parent and position of the source node
            let finalPosition = source[parentIdField] === destination[parentIdField]
                ? source[positionField] > destination[positionField]
                    ? destination[positionField] + 1
                    : destination[positionField]
                : position < 0
                    ? 0
                    : position;
            if (position === -1) {
                finalPosition = 0;
            }
            await dataProvider.update(resource, {
                id: source.id,
                data: {
                    // Set parent to null if moving to root (can't set to undefined as that would keep the previous parent)
                    [parentIdField]: destination[parentIdField] ?? null,
                    [positionField]: finalPosition,
                },
                previousData: source,
                meta,
            });
            return { data: undefined };
        },
        addRootNode: async (resource, { data, meta }) => {
            // get root records to compute position
            const { data: roots } = await dataProvider.getList(resource, {
                filter: { [parentIdField]: null },
                sort: { field: positionField, order: 'ASC' },
                pagination: { page: 1, perPage: 1000 },
                meta,
            });
            const rootPosition = roots.length > 0
                ? roots.reduce((acc, curr) => curr[positionField] > acc
                    ? curr[positionField]
                    : acc, -Infinity) + 1
                : 0;
            const { data: newRoot } = await dataProvider.create(resource, {
                data: {
                    ...data,
                    [parentIdField]: null,
                    [positionField]: rootPosition,
                },
                meta,
            });
            return { data: { ...newRoot, children: [] } };
        },
        addChildNode: async (resource, { parentId, data, meta, position }) => {
            // get child records to compute position
            const { data: siblings } = await dataProvider.getList(resource, {
                filter: { [parentIdField]: parentId },
                sort: { field: positionField, order: 'ASC' },
                pagination: { page: 1, perPage: 1000 },
                meta,
            });
            // there may be holes in the position sequence, so we can't just take the last position
            const maxPosition = siblings.length > 0
                ? siblings.reduce((acc, curr) => curr[positionField] > acc
                    ? curr[positionField]
                    : acc, -Infinity) + 1
                : 0;
            const childPosition = position !== undefined &&
                position >= 0 &&
                position <= maxPosition
                ? position
                : maxPosition;
            const { data: newRoot } = await dataProvider.create(resource, {
                data: {
                    ...data,
                    [parentIdField]: parentId,
                    [positionField]: childPosition,
                },
                meta,
            });
            if (position !== undefined &&
                position >= 0 &&
                position <= maxPosition) {
                siblings.forEach(sibling => {
                    if (sibling[positionField] >= position)
                        dataProvider.update(resource, {
                            id: sibling.id,
                            data: {
                                ...sibling,
                                [positionField]: sibling[positionField] + 1,
                            },
                            previousData: sibling,
                            meta,
                        });
                });
            }
            return { data: { ...newRoot, children: [] } };
        },
        deleteBranch: async (resource, params) => {
            const { id, previousData, meta } = params;
            // Deletion of the record itself must be handled by specialized method.
            await deleteBranch(treeDataProvider, resource, params);
            // However, we must update the node siblings position.
            // get the siblings
            const { data: siblings } = await treeDataProvider.getChildNodes(resource, {
                parentId: previousData[parentIdField],
                meta,
            });
            // update the siblings position
            await Promise.all(siblings
                .filter(node => node[positionField] > previousData[positionField] &&
                node.id !== id)
                .map(node => dataProvider.update(resource, {
                id: node.id,
                data: {
                    ...node,
                    [positionField]: node[positionField] - 1,
                },
                previousData: node,
                meta,
            })));
            return { data: previousData };
        },
    };
    return treeDataProvider;
};
