import { useEffect, useMemo, useState } from 'react';
import { useGetResourceLabel, useTranslate, useResourceContext, useNotify, useEvent, } from 'react-admin';
import cloneDeep from 'lodash/cloneDeep';
import { useGetChildNodesCallback, useGetRootNodes, useGetTree, useGetTreeCallback, useMoveAsNthChildOf, useMoveAsNthSiblingOf, } from '../dataProvider';
import { useExpandedKeys } from '../util';
import { UNSAVED_NEW_NODE } from '../constants';
import { getNodeIdsRecursively } from './getNodesIdsRecursively';
export const useTreeController = (options) => {
    const translate = useTranslate();
    const resource = useResourceContext(options);
    if (resource == null) {
        throw new Error('The useTreeController hook must be used inside a ResourceContext or must be passed a resource prop.');
    }
    const getResourceLabel = useGetResourceLabel();
    const { lazy = false, filter = {}, mutationMode = 'undoable', meta, } = options;
    // load entire tree on mount if lazy loading is not enabled
    const treeState = useGetTree(resource, { filter, meta }, {
        enabled: !lazy,
    });
    // load only the root nodes on mount if lazy loading is enabled
    const rootNodesState = useGetRootNodes(resource, { filter, meta }, {
        enabled: lazy,
        // FIXME - workaround for issues when loading the tree a second time
        // (e.g. when switching from a resource to another and back)
        gcTime: 0,
    });
    const innerLoadChildNodes = useGetChildNodesCallback(resource, {
        meta,
    });
    // remove the children in lazy mode, otherwise rc-tree won't offer to load them
    const lazyDataWithoutChildren = useMemo(() => rootNodesState.data?.map(record => {
        const { children, ...rest } = record;
        return children?.length ? rest : record;
    }), 
    // FIXME: Force a recompute when the root nodes are being fetched to avoid issues with new nodes in lazy mode
    // eslint-disable-next-line react-hooks/exhaustive-deps
    [rootNodesState.data, rootNodesState.isFetching]);
    const { data, error, isLoading, isPending, isFetching } = lazy
        ? {
            ...rootNodesState,
            data: lazyDataWithoutChildren,
        }
        : treeState;
    const [finalData, setFinalData] = useState(data);
    const loadChildNodes = useEvent(async (parentId) => {
        const records = await innerLoadChildNodes(parentId);
        setFinalData(previous => {
            // remove the children in lazy mode, otherwise rc-tree won't offer to load them
            const recordsWithoutChildren = records.map(record => {
                const { children, ...rest } = record;
                const childrenAreLoaded = previous?.some(node => record.children?.includes(node.id));
                return children?.length && !childrenAreLoaded ? rest : record;
            });
            const updated = [
                ...(previous?.map(node => {
                    if (node.id === parentId) {
                        return {
                            ...node,
                            // now we can set the children for rc-tree
                            children: recordsWithoutChildren.map(record => record.id),
                        };
                    }
                    return node;
                }) ?? []),
                ...recordsWithoutChildren,
            ];
            // If loadChildNodes is called multiple times on the same node,
            // we need to make sure we don't duplicate the children in the tree.
            // So we search for duplicates and only keep the last instance.
            const updatedAsMap = updated.reduce((acc, curr) => {
                acc[curr.id] = curr;
                return acc;
            }, {});
            return Object.values(updatedAsMap);
        });
    });
    useEffect(() => {
        setFinalData(data);
    }, [data]);
    // Node creation support
    const [newNode, setNewNode] = useState();
    const handleAddNode = useEvent((nodeToCreate) => {
        const newNodes = cloneDeep(finalData);
        if (nodeToCreate) {
            setNewNode(nodeToCreate);
            if (nodeToCreate.parentId != null) {
                const parentNode = newNodes?.find(node => node.id === nodeToCreate.parentId);
                if (parentNode) {
                    parentNode.children = parentNode.children || [];
                    parentNode.children = nodeToCreate.insertAsFirstChild
                        ? [UNSAVED_NEW_NODE, ...parentNode.children]
                        : [...parentNode.children, UNSAVED_NEW_NODE];
                }
            }
            setFinalData([
                ...(newNodes ?? []),
                // @ts-ignore
                {
                    id: UNSAVED_NEW_NODE,
                    children: [],
                    ...nodeToCreate.record,
                },
            ]);
        }
        else {
            if (!newNode)
                return;
            const newNodes = cloneDeep(finalData);
            if (newNode.parentId != null) {
                const parentNode = newNodes?.find(node => node.id === newNode.parentId);
                if (parentNode) {
                    parentNode.children = parentNode.children?.filter(node => node != UNSAVED_NEW_NODE);
                }
            }
            setNewNode(undefined);
            setFinalData(newNodes?.filter(record => record.id !== UNSAVED_NEW_NODE));
        }
    });
    const [expandedKeys, setExpandedKeys] = useExpandedKeys(undefined, options.expandedKeys);
    const handleExpand = useEvent((value) => {
        setExpandedKeys(previousValue => {
            const newValue = typeof value === 'function'
                ? value(previousValue ?? [])
                : value;
            const closedNodes = previousValue?.filter(key => !newValue.includes(key)) ?? [];
            const allClosedNodes = closedNodes?.flatMap(nodeKey => getNodeIdsRecursively(nodeKey, finalData ?? []), []) ?? [];
            return newValue.filter(key => !allClosedNodes.includes(key));
        });
    });
    // prepare hooks for drag and drop
    const [moveAsNthChildOf] = useMoveAsNthChildOf(resource, { meta });
    const [moveAsNthSiblingOf] = useMoveAsNthSiblingOf(resource, { meta });
    const refreshTree = useGetTreeCallback(resource);
    const notify = useNotify();
    /**
     * Call dataProvider.moveXXX() method on drop.
     *
     * Heavily inspired by https://github.com/react-component/tree/blob/master/examples/draggable.jsx
     *
     * @see https://github.com/react-component/tree/blob/master/examples/draggable.jsx
     */
    const handleDrop = useEvent(({ type, ...data }) => {
        // refresh tree on success
        const successSideEffect = async () => {
            await refreshTree();
            notify('ra-tree.item_moved', {
                undoable: mutationMode === 'undoable',
            });
        };
        const errorSideEffect = async (error) => {
            notify(error.message, {
                type: 'error',
            });
        };
        if (type === 'child') {
            // Drop on a node
            // move dragObject as first child of targetObject
            moveAsNthChildOf(resource, data, {
                // TODO: allow setting mutationOptions
                onSuccess: successSideEffect,
                onError: errorSideEffect,
                mutationMode,
            });
        }
        else {
            // drop between nodes
            // move dragObject to sibling targetPosition of targetObject
            moveAsNthSiblingOf(resource, data, {
                // TODO: allow setting mutationOptions
                onSuccess: successSideEffect,
                onError: errorSideEffect,
                mutationMode,
            });
        }
    });
    const defaultTitle = translate('ra.page.list', {
        name: getResourceLabel(resource, 2),
    });
    return {
        data: finalData,
        defaultTitle,
        error,
        expandedKeys,
        handleAddNode,
        handleDrop,
        handleExpand,
        isLoading,
        isFetching,
        // Because the tree is computed from our data, the isPending state must be controlled by us
        // If tree is null, we have not yet built it from the data
        isPending: isPending,
        loadChildNodes,
        newNode,
        lazy,
        setFinalData,
    };
};
