import { useGetTree } from '../dataProvider';
export const useReferenceNodeInputController = (props) => {
    const { reference: resource, source, meta } = props;
    const { data, error, isLoading, isFetching } = useGetTree(resource, {
        meta,
    });
    return {
        source,
        resource,
        data,
        error: error ?? undefined,
        isLoading,
        isFetching,
    };
};
