import { useRef } from 'react';
import { useMutation, useQueryClient, } from '@tanstack/react-query';
import { undoableEventEmitter, useDataProvider, } from 'react-admin';
import cloneDeep from 'lodash/cloneDeep';
/**
 * Get a callback to call the dataProvider.moveAsNthChildOf() method, the result and the loading state.
 *
 * @param {string} resource
 * @param {Params} params The moveAsNthChildOf parameters { id, previousData }
 * @param {Object} options Options object to pass to the queryClient.
 * May include side effects to be executed upon success or failure, e.g. { onSuccess: () => { refresh(); } }
 * May include a mutation mode (optimistic/pessimistic/undoable), e.g. { mutationMode: 'undoable' }
 *
 * @typedef Params
 * @prop params.id The resource identifier, e.g. 123
 * @prop params.previousData The record before the update is applied
 *
 * @returns The current mutation state. Destructure as [moveAsNthChildOf, { data, error, isLoading }].
 *
 * The return value updates according to the request state:
 *
 * - initial: [moveAsNthChildOf, { isLoading: false, isIdle: true }]
 * - start:   [moveAsNthChildOf, { isLoading: true }]
 * - success: [moveAsNthChildOf, { data: [data from response], isLoading: false, isSuccess: true }]
 * - error:   [moveAsNthChildOf, { error: [error from response], isLoading: false, isError: true }]
 *
 * The moveAsNthChildOf() function must be called with a resource and a parameter object: moveAsNthChildOf(resource, { id, previousData, meta }, options)
 *
 * This hook uses react-query useMutation under the hood.
 * This means the state object contains mutate, isIdle, reset and other react-query methods.
 *
 * @see https://react-query.tanstack.com/reference/useMutation
 *
 * @example // set params when calling the moveAsNthChildOf callback
 *
 * import { useMoveAsNthChildOf } from '@react-admin/ra-tree';
 *
 * const MoveAsNthChildOfButton = ({ record }) => {
 *     const [moveAsNthChildOf, { isLoading, error }] = useMoveAsNthChildOf();
 *     const handleClick = () => {
 *         moveAsNthChildOf('nodes', { id: record.id }, record)
 *     }
 *     if (error) { return <p>ERROR</p>; }
 *     return <button disabled={isLoading} onClick={handleClick}>Delete</div>;
 * };
 *
 * @example // set params when calling the hook
 *
 * import { useMoveAsNthChildOf } from '@react-admin/ra-tree';
 *
 * const DeleteButton = ({ record }) => {
 *     const [moveAsNthChildOf, { isLoading, error }] = useMoveAsNthChildOf('nodes', { id: record.id }, record);
 *     if (error) { return <p>ERROR</p>; }
 *     return <button disabled={isLoading} onClick={() => moveAsNthChildOf()}>Delete</button>;
 * };
 *
 * @example // TypeScript
 * const [delete, { data }] = useMoveAsNthChildOf<Product>('products', { id, previousData: product });
 *                    \-- data is Product
 */
export const useMoveAsNthChildOf = (resource, params = {
    source: undefined,
    destination: undefined,
    position: undefined,
    meta: undefined,
}, options = {}) => {
    const dataProvider = useDataProvider();
    const queryClient = useQueryClient();
    const { source, destination, position } = params;
    const { mutationMode = 'undoable', ...reactMutationOptions } = options;
    const mode = useRef(mutationMode);
    const paramsRef = useRef(params);
    const snapshot = useRef([]);
    const updateCache = ({ resource, position, source, destination, }) => {
        // hack: only way to tell react-query not to fetch this query for the next 5 seconds
        // because setQueryData doesn't accept a stale time option
        const now = Date.now();
        const updatedAt = mode.current === 'undoable' ? now + 5 * 1000 : now;
        const updateCollection = (old) => {
            let newRecords = cloneDeep(old);
            // Remove the node from its previous parent
            const oldParent = newRecords.find(record => record.children?.includes(source.id));
            if (oldParent) {
                oldParent.children = oldParent.children?.filter(childId => childId !== source.id);
            }
            else {
                // It's a root node
                newRecords = newRecords.filter(record => record.id !== source.id);
            }
            // Add the node to the new parent
            const newParent = newRecords.find(record => record.id === destination.id);
            if (newParent) {
                newParent.children = [
                    ...(newParent.children?.slice(0, position) ?? []),
                    source.id,
                    ...(newParent.children?.slice(position) ?? []),
                ];
            }
            else {
                // It's a root node
                newRecords = newRecords.filter(record => record.id !== source.id);
                newRecords = [
                    ...newRecords.slice(0, position),
                    source,
                    ...newRecords.slice(position),
                ];
            }
            return newRecords;
        };
        queryClient.setQueriesData({
            queryKey: [resource, 'getTree'],
        }, (res) => res && res.length > 0 ? updateCollection(res) : res, { updatedAt });
        queryClient.setQueriesData({
            queryKey: [resource, 'getRootNodes'],
        }, (res) => res && res.length > 0 ? updateCollection(res) : res, { updatedAt });
        queryClient.setQueriesData({
            queryKey: [resource, 'getChildNodes'],
        }, (res) => res && res.length > 0 ? updateCollection(res) : res, { updatedAt });
    };
    const mutation = useMutation({
        mutationFn: ({ resource: callTimeResource = resource, position: callTimePosition = paramsRef.current.position, source: callTimeSource = paramsRef.current.source, destination: callTimeDestination = paramsRef.current.destination, meta: callTimeMeta = paramsRef.current.meta, } = {}) => {
            if (callTimeResource == null) {
                throw new Error('useMoveAsNthChildOf mutation requires a non-empty resource');
            }
            if (callTimePosition == null) {
                throw new Error('useMoveAsNthChildOf mutation requires a non-empty position');
            }
            if (callTimeSource == null) {
                throw new Error('useMoveAsNthChildOf mutation requires a non-empty source');
            }
            if (callTimeDestination == null) {
                throw new Error('useMoveAsNthChildOf mutation requires a non-empty destination');
            }
            return dataProvider
                .moveAsNthChildOf(callTimeResource, {
                position: callTimePosition,
                source: callTimeSource,
                destination: callTimeDestination,
                meta: callTimeMeta,
            })
                .then(({ data }) => data);
        },
        ...reactMutationOptions,
        onMutate: async (variables) => {
            if (reactMutationOptions.onMutate) {
                const userContext = (await reactMutationOptions.onMutate(variables)) || {};
                return {
                    snapshot: snapshot.current,
                    // @ts-ignore
                    ...userContext,
                };
            }
            else {
                // Return a context object with the snapshot value
                return { snapshot: snapshot.current };
            }
        },
        onError: (error, variables, context) => {
            if (mode.current === 'optimistic' || mode.current === 'undoable') {
                // If the mutation fails, use the context returned from onMutate to rollback
                context.snapshot.forEach(([key, value]) => {
                    queryClient.setQueryData(key, value);
                });
            }
            if (reactMutationOptions.onError) {
                return reactMutationOptions.onError(error, variables, context);
            }
            // call-time error callback is executed by react-query
        },
        onSettled: (data, error, variables = {}, context) => {
            // Moving a node might have updated other nodes, so we need to invalidate the cache in all cases
            const { resource: callTimeResource = resource } = variables;
            queryClient.invalidateQueries({
                queryKey: [callTimeResource, 'getTree'],
            });
            queryClient.invalidateQueries({
                queryKey: [callTimeResource, 'getRootNodes'],
            });
            queryClient.invalidateQueries({
                queryKey: [callTimeResource, 'getChildNodes'],
            });
            if (reactMutationOptions.onSettled) {
                return reactMutationOptions.onSettled(data, error, variables, context);
            }
        },
    });
    const mutate = async (callTimeResource = resource, callTimeParams = {}, callTimeOptions = {}) => {
        const { mutationMode, onSuccess, onSettled, onError } = callTimeOptions;
        // store the hook time params *at the moment of the call*
        // because they may change afterwards, which would break the undoable mode
        // as the previousData would be overwritten by the optimistic update
        paramsRef.current = params;
        if (mutationMode) {
            mode.current = mutationMode;
        }
        if (mode.current === 'pessimistic') {
            return mutation.mutate({ resource: callTimeResource, ...callTimeParams }, { onSuccess, onSettled, onError });
        }
        const { position: callTimePosition = position, source: callTimeSource = source, destination: callTimeDestination = destination, } = callTimeParams;
        if (callTimeResource == null) {
            throw new Error('useMoveAsNthChildOf mutation requires a non-empty resource');
        }
        if (callTimePosition == null) {
            throw new Error('useMoveAsNthChildOf mutation requires a non-empty position');
        }
        if (callTimeSource == null) {
            throw new Error('useMoveAsNthChildOf mutation requires a non-empty source');
        }
        if (callTimeDestination == null) {
            throw new Error('useMoveAsNthChildOf mutation requires a non-empty destination');
        }
        // optimistic update as documented in https://react-query.tanstack.com/guides/optimistic-updates
        // except we do it in a mutate wrapper instead of the onMutate callback
        // to have access to success side effects
        const queryKeys = [
            [callTimeResource, 'getTree'],
            [callTimeResource, 'getRootNodes'],
            [callTimeResource, 'getChildNodes'],
        ];
        /**
         * Snapshot the previous values via queryClient.getQueriesData()
         *
         * The snapshotData ref will contain an array of tuples [query key, associated data]
         *
         * @example
         * [
         *   [['posts', 'getList'], { data: [{ id: 1, title: 'Hello' }], total: 1 }],
         *   [['posts', 'getMany'], [{ id: 1, title: 'Hello' }]],
         * ]
         *
         * @see https://react-query.tanstack.com/reference/QueryClient#queryclientgetqueriesdata
         */
        snapshot.current = queryKeys.reduce((prev, curr) => prev.concat(queryClient.getQueriesData({ queryKey: curr })), []);
        // Cancel any outgoing re-fetches (so they don't overwrite our optimistic update)
        await Promise.all(snapshot.current.map(([key]) => queryClient.cancelQueries({ queryKey: key })));
        // Optimistically update to the new value
        updateCache({
            resource: callTimeResource,
            position: callTimePosition,
            source: callTimeSource,
            destination: callTimeDestination,
        });
        // run the success callbacks during the next tick
        if (onSuccess) {
            setTimeout(() => onSuccess(undefined, { resource: callTimeResource, ...callTimeParams }, { snapshot: snapshot.current }), 0);
        }
        if (reactMutationOptions.onSuccess) {
            setTimeout(() => {
                if (reactMutationOptions.onSuccess) {
                    reactMutationOptions.onSuccess(undefined, { resource: callTimeResource, ...callTimeParams }, { snapshot: snapshot.current });
                }
            }, 0);
        }
        if (mode.current === 'optimistic') {
            // call the mutate method without success side effects
            return mutation.mutate({ resource: callTimeResource, ...callTimeParams }, { onSettled, onError });
        }
        else {
            // undoable mutation: register the mutation for later
            undoableEventEmitter.once('end', ({ isUndo }) => {
                if (isUndo) {
                    // rollback
                    snapshot.current.forEach(([key, value]) => {
                        queryClient.setQueryData(key, value);
                    });
                }
                else {
                    // call the mutate method without success side effects
                    mutation.mutate({ resource: callTimeResource, ...callTimeParams }, { onSettled, onError });
                }
            });
        }
    };
    return [mutate, mutation];
};
