import { useMemo } from 'react';
import { useBasename, useLocation, useMatch } from 'react-admin';
/**
 * react-router keeps the basename in `pathname`, ra-router-tanstack strips it,
 * hence the runtime check. The match is not referentially stable on every
 * provider: never put it in a dependency array.
 */
export function useMatchWithBasename(path) {
    const basename = useBasename();
    const { pathname } = useLocation();
    const pattern = useMemo(() => {
        const carriesBasename = !!basename &&
            (pathname === basename || pathname.startsWith(`${basename}/`));
        return { path: `${carriesBasename ? basename : ''}${path}` };
    }, [basename, pathname, path]);
    return useMatch(pattern);
}
