import { createContext, useContext } from 'react';
const NodeActionsContext = createContext(null);
export const NodeActionsContextProvider = NodeActionsContext.Provider;
export const useNodeActionsContext = () => {
    const context = useContext(NodeActionsContext);
    if (!context) {
        throw new Error('useNodeActionsContext must be used within a NodeActionsContextProvider');
    }
    return context;
};
