/**
 * Helper method to workaround the inability of FakeRest to filter by null values
 * @param dataProvider the base dataProvider
 * @returns a dataProvider with a patched `getRootNodes` method, that will only keep nodes where `node.parent_id === 'undefined'`
 */
export const fixFakeRestDataProvider = dataProvider => ({
    ...dataProvider,
    getRootNodes: async (resource, params) => {
        const { data } = await dataProvider.getRootNodes(resource, params);
        const filteredNodes = data.filter(node => node.parent_id == null);
        return {
            data: filteredNodes,
            total: filteredNodes.length,
        };
    },
    addRootNode: async (resource, { data, meta }) => {
        // get root records to compute position
        const { data: roots } = await dataProvider.getList(resource, {
            filter: { parent_id: null },
            sort: { field: 'position', order: 'ASC' },
            pagination: { page: 1, perPage: 1000 },
            meta,
        });
        const filteredRoots = roots.filter(node => typeof node.parent_id === 'undefined');
        const rootPosition = filteredRoots.length > 0
            ? filteredRoots.reduce((acc, curr) => curr['position'] > acc ? curr['position'] : acc, -Infinity) + 1
            : 0;
        const { data: newRoot } = await dataProvider.create(resource, {
            data: {
                ...data,
                parent_id: null,
                position: rootPosition,
            },
            meta,
        });
        return { data: { ...newRoot, children: [] } };
    },
});
