import { useCallback, useState, } from 'react';
import { useNotify, useRecordContext, useRedirect, useRefresh, useResourceContext, } from 'react-admin';
import { useDeleteBranch } from '../dataProvider';
import { useTreeContext } from './useTreeContext';
import { removeNode } from '../util/removeNode';
/**
 * Prepare a set of callbacks for a delete branch button guarded by confirmation dialog
 *
 * @example
 *
 * const DeleteBranchButton = ({
 *     resource,
 *     record,
 *     redirect,
 *     onClick,
 *     ...rest
 * }) => {
 *     const {
 *         open,
 *         isPending,
 *         handleDialogOpen,
 *         handleDialogClose,
 *         handleDelete,
 *     } = useDeleteBranchWithConfirmController({
 *         resource,
 *         record,
 *         redirect,
 *         onClick,
 *     });
 *
 *     return (
 *         <Fragment>
 *             <Button
 *                 onClick={handleDialogOpen}
 *                 label="ra.action.delete"
 *                 {...rest}
 *             >
 *                 {icon}
 *             </Button>
 *             <Confirm
 *                 isOpen={open}
 *                 loading={isPending}
 *                 title="ra.message.delete_title"
 *                 content="ra.message.delete_content"
 *                 translateOptions={{
 *                     name: resource,
 *                     id: record.id,
 *                 }}
 *                 onConfirm={handleDelete}
 *                 onClose={handleDialogClose}
 *             />
 *         </Fragment>
 *     );
 * };
 */
export const useDeleteBranchWithConfirmController = (props) => {
    const { mutationMode, mutationOptions, redirect: redirectTo = 'list', } = props;
    const notify = useNotify();
    const redirect = useRedirect();
    const refresh = useRefresh();
    const resource = useResourceContext(props);
    if (resource == null) {
        throw new Error('The useDeleteBranchWithConfirmController hook must be used inside a ResourceContext or must be passed a resource prop.');
    }
    const record = useRecordContext(props);
    if (record == null) {
        throw new Error('The useDeleteBranchWithConfirmController hook must be used inside a RecordContext or must be passed a record prop.');
    }
    const [deleteBranch, { isPending }] = useDeleteBranch();
    const [open, setOpen] = useState(false);
    const { setFinalData } = useTreeContext();
    const handleDelete = useCallback(event => {
        event.stopPropagation();
        deleteBranch(resource, {
            id: record.id,
            previousData: record,
        }, {
            mutationMode,
            onSuccess: () => {
                notify('ra.notification.deleted', {
                    type: 'info',
                    messageArgs: { smart_count: 1 },
                });
                redirect(redirectTo, resource);
                if (mutationMode === 'pessimistic') {
                    refresh();
                }
                else {
                    setFinalData &&
                        setFinalData(previous => removeNode(previous, record));
                }
            },
            onError: error => {
                notify(typeof error === 'string'
                    ? error
                    : error.message || 'ra.notification.http_error', { type: 'warning' });
            },
            ...mutationOptions,
        });
    }, [
        deleteBranch,
        mutationMode,
        mutationOptions,
        notify,
        record,
        redirect,
        redirectTo,
        refresh,
        resource,
        setFinalData,
    ]);
    const handleDialogOpen = e => {
        e.stopPropagation();
        setOpen(true);
    };
    const handleDialogClose = e => {
        e.stopPropagation();
        setOpen(false);
    };
    return {
        handleDelete,
        handleDialogOpen,
        handleDialogClose,
        isPending,
        open,
    };
};
