import { useCallback } from 'react';
import { useNotify, useRecordContext, useRedirect, useResourceContext, } from 'react-admin';
import { useDeleteBranch } from '../dataProvider';
import { useTreeContext } from './useTreeContext';
import { removeNode } from '../util/removeNode';
/**
 * Prepare callback for a delete branch button with undo support
 *
 * @example
 *
 * import React from 'react';
 * import ActionDelete from '@material-ui/icons/Delete';
 * import { Button, useDeleteBranchWithUndoController } from '@react-admin/ra-tree';
 *
 * const DeleteButton = ({
 *     resource,
 *     record,
 *     basePath,
 *     redirect,
 *     onClick,
 *     ...rest
 * }) => {
 *     const [handleDelete, { isPending }] = useDeleteBranchWithUndoController({
 *         resource,
 *         record,
 *         redirect,
 *     });
 *
 *     const handleClick = () => {
 *         handleDelete();
 *     }
 *
 *     return (
 *         <Button
 *             onClick={handleClick}
 *             disabled={isPending}
 *             label="ra.action.delete"
 *             {...rest}
 *         >
 *             <ActionDelete />
 *         </Button>
 *     );
 * };
 */
export const useDeleteBranchWithUndoController = (props) => {
    const { mutationOptions, redirect: redirectTo = 'list' } = props;
    const notify = useNotify();
    const redirect = useRedirect();
    const { setFinalData } = useTreeContext();
    const resource = useResourceContext(props);
    if (resource == null) {
        throw new Error('The useDeleteBranchWithUndoController hook must be used inside a ResourceContext or must be passed a resource prop.');
    }
    const record = useRecordContext(props);
    if (record == null) {
        throw new Error('The useDeleteBranchWithUndoController hook must be used inside a RecordContext or must be passed a record prop.');
    }
    const [deleteBranch, { isPending }] = useDeleteBranch();
    const handleDelete = useCallback(event => {
        event.stopPropagation();
        deleteBranch(resource, {
            id: record.id,
            previousData: record,
        }, {
            onSuccess: () => {
                notify('ra.notification.deleted', {
                    type: 'info',
                    messageArgs: { smart_count: 1 },
                    undoable: true,
                });
                if (setFinalData) {
                    setFinalData(previous => removeNode(previous, record));
                }
                redirect(redirectTo, resource);
            },
            onError: error => notify(typeof error === 'string'
                ? error
                : error.message || 'ra.notification.http_error', { type: 'warning' }),
            mutationMode: 'undoable',
            ...mutationOptions,
        });
    }, [
        deleteBranch,
        mutationOptions,
        notify,
        record,
        redirect,
        redirectTo,
        resource,
        setFinalData,
    ]);
    return { handleDelete, isPending };
};
