import { useRef } from 'react';
import { useMutation, useQueryClient, } from '@tanstack/react-query';
import { useDataProvider } from 'react-admin';
/**
 * Get a callback to call the dataProvider.addRootNode() method, the result and the loading state.
 *
 * @param {string} resource
 * @param {Params} params The addRootNode parameters { data }
 * @param {Object} options Options object to pass to the queryClient.
 * May include side effects to be executed upon success or failure, e.g. { onSuccess: () => { refresh(); } }
 *
 * @typedef Params
 * @prop params.data The record to add as a root node, e.g. { title: 'hello, world' }
 *
 * @returns The current mutation state. Destructure as [addRootNode, { data, error, isLoading }].
 *
 * The return value updates according to the request state:
 *
 * - initial: [addRootNode, { isLoading: false, isIdle: true }]
 * - start:   [addRootNode, { isLoading: true }]
 * - success: [addRootNode, { data: [data from response], isLoading: false, isSuccess: true }]
 * - error:   [addRootNode, { error: [error from response], isLoading: false, isError: true }]
 *
 * The addRootNode() function must be called with a resource and a parameter object: addRootNode(resource, { data, meta }, options)
 *
 * This hook uses react-query useMutation under the hood.
 * This means the state object contains mutate, isIdle, reset and other react-query methods.
 *
 * @see https://react-query.tanstack.com/reference/useMutation
 *
 * @example // set params when calling the addRootNode callback
 *
 * import { useAddRootNode } from '@react-admin/ra-tree';
 *
 * const AddNodeButton = () => {
 *     const node = { title: 'a root node' };
 *     const [addRootNode, { isLoading, error }] = useAddRootNode();
 *     const handleClick = () => {
 *         addRootNode('nodes', { data: node })
 *     }
 *     if (error) { return <p>ERROR</p>; }
 *     return <button disabled={isLoading} onClick={() => addRootNode()}>Add a new root node</button>;
 * };
 *
 * @example // set params when calling the hook
 *
 * import { useAddRootNode } from '@react-admin/ra-tree';
 *
 * const AddNodeButton = () => {
 *     const node = { title: 'a root node' };
 *     const [addRootNode, { isLoading, error }] = useAddRootNode('nodes', { data: node });
 *     if (error) { return <p>ERROR</p>; }
 *     return <button disabled={isLoading} onClick={() => addRootNode()}>Add a new root node</button>;
 * };
 *
 * @example // TypeScript
 * const [addRootNode, { data }] = useAddRootNode<Product>('products', { data: product });
 *                    \-- data is Product
 */
export const useAddRootNode = (resource, params = {}, options = {}) => {
    const dataProvider = useDataProvider();
    const queryClient = useQueryClient();
    const paramsRef = useRef(params);
    const mutation = useMutation({
        mutationFn: ({ resource: callTimeResource = resource, data: callTimeData = paramsRef.current.data, meta: callTimeMeta = paramsRef.current.meta, } = {}) => {
            if (!callTimeResource) {
                throw new Error('useAddRootNode mutation requires a non-empty resource');
            }
            if (callTimeData == null) {
                throw new Error('useAddRootNode mutation requires non-empty data');
            }
            return dataProvider
                .addRootNode(callTimeResource, {
                data: callTimeData,
                meta: callTimeMeta,
            })
                .then(({ data }) => data);
        },
        ...options,
        onSuccess: (data, variables = {}, context) => {
            const { resource: callTimeResource = resource } = variables;
            queryClient.setQueryData([callTimeResource, 'getOne', { id: String(data.id) }], data);
            if (options.onSuccess) {
                options.onSuccess(data, variables, context);
            }
            // call-time success callback is executed by react-query
        },
    });
    const addRootNode = async (callTimeResource = resource, callTimeParams = {}, callTimeOptions = {}) => {
        const { returnPromise, ...otherOptions } = callTimeOptions;
        if (returnPromise) {
            return mutation.mutateAsync({ resource: callTimeResource, ...callTimeParams }, callTimeOptions);
        }
        mutation.mutate({ resource: callTimeResource, ...callTimeParams }, otherOptions);
    };
    return [addRootNode, mutation];
};
